namespace InvoiceLib;

/// <summary>
/// Ambient time abstraction for testability.
/// Production code calls <see cref="UtcNow"/>; tests pin the time with <see cref="Override"/>.
/// Uses <see cref="AsyncLocal{T}"/> so parallel tests don't interfere with each other.
/// </summary>
public static class Clock
{
    private static readonly AsyncLocal<Func<DateTimeOffset>?> s_override = new();

    public static DateTimeOffset UtcNow
        => s_override.Value?.Invoke() ?? DateTimeOffset.UtcNow;

    /// <summary>
    /// Pins <see cref="UtcNow"/> to <paramref name="fixedTime"/> for the current async flow.
    /// Dispose the returned value to restore normal behaviour.
    /// </summary>
    public static IDisposable Override(DateTimeOffset fixedTime)
    {
        s_override.Value = () => fixedTime;
        return new Scope();
    }

    private sealed class Scope : IDisposable
    {
        public void Dispose() => s_override.Value = null;
    }
}

